337: async function reconcileRemoteCanvasUnlocked(input: {
338:     id: string;
339:     remote: CanvasProject;
340:     expected: CapturedUserScope;
341:     hadLive: boolean;
342:     onApplied?: (project: CanvasProject, previous: CanvasProject | undefined) => void;
343: }): Promise<RemoteReconcileOutcome> {
344:     const { id, remote, expected } = input;
345:     const scope = expected.userScope;
346:     if (!matchesDispatchGuard(expected) || canvasDeleting.has(saveKey(scope, id))) return { kind: "skipped" };
347:     const journal = peekCanvasOperationJournal(id, scope);
348:     if (journal?.confirmedSnapshot && typeof remote.revision === "number" && remote.revision <= journal.confirmedRevision) return { kind: "stale" };
349:     if (canvasSubmitBlocked(id, scope)) {
350:         pauseForExternalCandidate(id, remote, scope);
351:         return { kind: "held" };
352:     }
353:     if (journal?.inFlight) return { kind: "deferred" };
354:     const base = journal?.pendingProjection?.base
355:         ?? journal?.confirmedSnapshot
356:         ?? canvasDocumentBase(id, scope)?.snapshot
357:         ?? null;
358:     const live = openLocalCanvasProject(id);
359:     if (live && remoteRebaseConflicts(base, live, remote)) {
360:         pauseForExternalCandidate(id, remote, scope);
361:         return { kind: "held" };
362:     }
363:     let confirmed;
364:     try {
365:         confirmed = await confirmRemoteDocument(remote, scope);
366:     } catch (error) {
367:         rethrowIfAbandoned(error);
368:         return { kind: "skipped" };
369:     }
370:     if ((remote.revision ?? 0) < confirmed.confirmedRevision) return { kind: "stale" };
371:     if (input.hadLive && !openLocalCanvasProject(id)) return { kind: "skipped" };
372:     const project = alignLiveAfterConfirmedRemote({
373:         id,
374:         scope,
375:         remote,
376:         base,
377:         hadLive: input.hadLive,
378:         expected,
379:         onApplied: input.onApplied,
380:     });
381:     await persistProjectedCanvas(id, scope, confirmed.pendingProjection?.identity, { throwOnFailure: false }, expected);
382:     // 等待日记写入期间用户可能又改了同一字段：合并时会转成冲突暂停。
383:     if (canvasSubmitBlocked(id, scope)) return { kind: "held" };
384:     const current = openLocalCanvasProject(id);
385:     const confirmedSnapshot = confirmed.confirmedSnapshot ?? remote;
386:     return { kind: "applied", project, unconfirmed: Boolean(current && !sameCanvasDocument(current, confirmedSnapshot)) };
387: }
