36: /**
37:  * 索引只接受「右下严格大于左上」的矩形，而端口锚点落在节点边界上（分镜行、批量表端口
38:  * 也一样），所以零尺寸卡片和左右/上下反向的卡片都必须先补成有效矩形，否则会被整条丢掉。
39:  */
40: function snapBounds(node: CanvasNodeData): CanvasSpatialBounds {
41:     const bounds = canvasNodeBounds(node);
42:     const left = Math.min(bounds.left, bounds.right);
43:     const right = Math.max(bounds.left, bounds.right);
44:     const top = Math.min(bounds.top, bounds.bottom);
45:     const bottom = Math.max(bounds.top, bounds.bottom);
46:     return right > left && bottom > top ? { left, top, right, bottom } : { left: left - 1, top: top - 1, right: right + 1, bottom: bottom + 1 };
47: }
