49: function nodeIndexFor(nodes: CanvasNodeData[]) {
50:     let index = nodeIndexCache.get(nodes);
51:     if (!index) {
52:         index = buildCanvasSpatialIndex(nodes.map((node) => ({ id: node.id, bounds: snapBounds(node), value: node })));
53:         nodeIndexCache.set(nodes, index);
54:     }
55:     return index;
56: }

