76:                 reason: response.data.reason,
77:                 details: response.data.details,
78:                 requestId: responseRequestId(response.headers),
79:                 retryable: isRetryableStatus(response.status) || isRetryableStatus(response.data.code),
80:                 retryAfterMs: retryAfterMilliseconds(response.headers),
